    <div className="settings-section"><h3>{t("language")}</h3><div className="language-options"><button type="button" className={language === "en" ? "selected" : ""} onClick={() => setLanguage("en")}>EN · {t("english")}</button><button type="button" className={language === "ar" ? "selected" : ""} onClick={() => setLanguage("ar")}>AR · {t("arabic")}</button></div></div>
