  useEffect(() => { localStorage.setItem(`sap-pinned-${userKey}`, JSON.stringify(pinned)); }, [pinned, userKey]); useEffect(() => { localStorage.setItem(`sap-projects-${userKey}`, JSON.stringify(projects)); }, [projects, userKey]);
  useEffect(() => { const textarea = composerRef.current; if (!textarea) return; textarea.style.height = "auto"; textarea.style.height = `${Math.min(180, Math.max(58, textarea.scrollHeight))}px`; textarea.style.overflowY = textarea.scrollHeight > 180 ? "auto" : "hidden"; }, [input]); useEffect(() => () => { abortRef.current?.abort(); speechRef.current?.stop(); }, []);
  useEffect(() => { const visible = conversations.filter((item) => item.title.toLowerCase().includes(search.toLowerCase())); const pinnedIds = new Set(pinned); const displayed = [...visible.filter((item) => pinnedIds.has(item.id)), ...visible.filter((item) => !pinnedIds.has(item.id))]; document.querySelectorAll<HTMLElement>(".sidebar-chat").forEach((button, index) => { const conversation = displayed[index]; let time = button.querySelector<HTMLElement>(".chat-time"); if (!conversation?.updated_at) { time?.remove(); return; } if (!time) { time = document.createElement("time"); time.className = "chat-time"; button.querySelector(".chat-title")?.append(time); } time.setAttribute("datetime", conversation.updated_at); time.textContent = formatConversationTime(conversation.updated_at); }); }, [conversations, pinned, search, language]);
  useEffect(() => { const guardImeEnter = (event: KeyboardEvent) => { if (event.isComposing && event.key === "Enter" && event.target instanceof HTMLTextAreaElement) { event.preventDefault(); event.stopImmediatePropagation(); } }; window.addEventListener("keydown", guardImeEnter, true); return () => window.removeEventListener("keydown", guardImeEnter, true); }, []);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { const modifier = event.ctrlKey || event.metaKey; if (modifier && event.key.toLowerCase() === "k") { event.preventDefault(); setSearchOpen(true); } if (modifier && event.shiftKey && event.key.toLowerCase() === "o") { event.preventDefault(); newChat(); } if (event.key === "Escape") { setSearchOpen(false); setSettingsOpen(false); setProfileOpen(false); setMobileSidebarOpen(false); } }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); });

  async function api(path: string, options: RequestInit = {}) { let requestOptions = options; if (typeof options.body === "string" && (path === "/chat/stream" || path.endsWith("/edit") || path.endsWith("/regenerate"))) { try { const payload = JSON.parse(options.body) as Record<string, unknown>; payload.response_language = selectedResponseLanguage || null; requestOptions = { ...options, body: JSON.stringify(payload) }; } catch { /* preserve the original request if its body is not JSON */ } } const response = await fetch(API + path, { ...requestOptions, headers: { Authorization: `Bearer ${token}`, ...requestOptions.headers } }); if (response.status === 401) { onLogout(); throw new Error("Session expired. Please sign in again."); } return response; }
  async function loadHistory(restore = false) { setLoadingHistory(true); setHistoryError(""); try { const response = await api("/conversations"); if (!response.ok) throw new Error("Could not load chat history."); const saved: Conversation[] = await response.json(); setConversations(saved); if (restore) { const stored = Number(localStorage.getItem("activeConversationId")); if (stored && saved.some((item) => item.id === stored)) await selectConversation(stored); else if (stored) { localStorage.removeItem("activeConversationId"); setActiveId(null); setMessages([]); } } } catch (cause) { setHistoryError(cause instanceof Error ? cause.message : "Could not load chat history."); } finally { setLoadingHistory(false); } }
  useEffect(() => { void loadHistory(true); }, [token]);
  async function selectConversation(id: number) { if (busy) return; const version = ++requestVersion.current; setHistoryError(""); try { const response = await api(`/conversations/${id}/messages`); if (!response.ok) { if (response.status === 404) throw new Error("Conversation not found"); throw new Error("Could not load this chat."); } const saved: Message[] = await response.json(); if (version !== requestVersion.current) return; setMessages(saved); setActiveId(id); localStorage.setItem("activeConversationId", String(id)); setMobileSidebarOpen(false); } catch (cause) { if (version === requestVersion.current) { if (cause instanceof Error && cause.message === "Conversation not found") { localStorage.removeItem("activeConversationId"); setActiveId(null); setMessages([]); } setHistoryError(cause instanceof Error ? cause.message : "Could not load this chat."); } } }
  function newChat() { if (busy) return; requestVersion.current += 1; setMessages([]); setActiveId(null); setEditingMessageIndex(null); setInput(""); setError(""); localStorage.removeItem("activeConversationId"); setMobileSidebarOpen(false); }
  async function attachTextFile(file?: File) { if (!file) return; try { const text = await file.text(); const addition = `${input.trim() ? "\n\n" : ""}[Attached file: ${file.name}]\n${text}`; if (input.length + addition.length > 12000) throw new Error("That file is too large to include in one message."); setInput((current) => current.trim() + addition); composerRef.current?.focus(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not read that file."); } }
  function toggleVoice() { if (speechRef.current) { speechRef.current.stop(); speechRef.current = null; setVoiceListening(false); return; } const speechWindow = window as Window & { SpeechRecognition?: new () => any; webkitSpeechRecognition?: new () => any }; const Recognition = speechWindow.SpeechRecognition || speechWindow.webkitSpeechRecognition; if (!Recognition) { setError("Voice input is not supported in this browser."); return; } const recognition = new Recognition(); recognition.lang = navigator.language || "en-US"; recognition.interimResults = false; recognition.onresult = (event: any) => { const value = event.results[0]?.[0]?.transcript?.trim(); if (value) setInput((current) => `${current.trim()}${current.trim() ? " " : ""}${value}`); }; recognition.onerror = () => { setError("Voice input could not start. Check microphone access."); setVoiceListening(false); speechRef.current = null; }; recognition.onend = () => { setVoiceListening(false); speechRef.current = null; }; speechRef.current = recognition; setVoiceListening(true); try { recognition.start(); } catch { setVoiceListening(false); speechRef.current = null; } }

  async function send() {
    const question = input.trim(); if (!question || busy) return; setInput(""); setError(""); setBusy(true);
    if (editingMessageIndex !== null && activeId !== null) { try { const response = await api(`/conversations/${activeId}/edit`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message_index: editingMessageIndex, message: question }) }); const data = await response.json(); if (!response.ok) throw new Error(data.detail || "Could not update this prompt."); setMessages((items) => [...items.slice(0, editingMessageIndex), { role: "user", content: question }, { role: "assistant", content: data.answer }]); setEditingMessageIndex(null); await loadHistory(); } catch (cause) { setInput(question); setError(cause instanceof Error ? cause.message : "Could not update this prompt."); } finally { setBusy(false); } return; }
    setMessages((items) => [...items, { role: "user", content: question }, { role: "assistant", content: "" }]); streamCancelledRef.current = false; const controller = new AbortController(); abortRef.current = controller;
    try { const response = await api("/chat/stream", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message: question, conversation_id: activeId }), signal: controller.signal }); if (!response.ok) { const data = await response.json().catch(() => ({})); throw new Error(data.detail || "Chat request failed."); } if (!response.body) throw new Error("The server did not provide a response stream."); const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = ""; let streamError = ""; let completed = false; const handle = (block: string) => { block.split("\n").forEach((line) => { if (!line.startsWith("data:")) return; const payload = line.slice(5).trim(); if (payload === "[DONE]") return; try { const event = JSON.parse(payload) as { token?: string; conversation_id?: number; error?: string; done?: boolean }; if (typeof event.conversation_id === "number") { setActiveId(event.conversation_id); localStorage.setItem("activeConversationId", String(event.conversation_id)); } if (event.token) setMessages((items) => { const index = items.length - 1; const last = items[index]; return last?.role === "assistant" ? [...items.slice(0, index), { ...last, content: last.content + event.token }] : items; }); if (event.error) streamError = event.error; if (event.done) completed = true; } catch { /* keep reading malformed frames */ } }); }; while (true) { const { done, value } = await reader.read(); if (done) break; buffer += decoder.decode(value, { stream: true }).replace(/\r\n/g, "\n"); let boundary = buffer.indexOf("\n\n"); while (boundary !== -1) { handle(buffer.slice(0, boundary)); buffer = buffer.slice(boundary + 2); boundary = buffer.indexOf("\n\n"); } } buffer += decoder.decode().replace(/\r\n/g, "\n"); if (buffer.trim()) handle(buffer); if (streamCancelledRef.current) return; if (streamError) throw new Error(streamError); if (!completed) throw new Error("The response stream ended before the answer was saved."); await loadHistory(); }
    catch (cause) { const expectedCancellation = streamCancelledRef.current || (cause instanceof DOMException && cause.name === "AbortError"); if (!expectedCancellation) { setMessages((items) => items.slice(0, -2)); if (cause instanceof Error && cause.message === "Conversation not found") { localStorage.removeItem("activeConversationId"); setActiveId(null); } setError(cause instanceof Error ? cause.message : "Unable to connect to the backend."); } } finally { abortRef.current = null; setBusy(false); }
  }
  function stopGeneration() { streamCancelledRef.current = true; abortRef.current?.abort(); abortRef.current = null; setMessages((items) => { const last = items[items.length - 1]; return last?.role === "assistant" && !last.content.trim() ? items.slice(0, -1) : items; }); setBusy(false); setError(""); }
  async function regenerate(index: number) { if (!activeId || busy || index !== messages.length - 1) return; setBusy(true); setError(""); try { const response = await api(`/conversations/${activeId}/regenerate`, { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" }); const data = await response.json(); if (!response.ok) throw new Error(data.detail || "Could not regenerate this response."); setMessages((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, content: data.answer } : item)); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not regenerate this response."); } finally { setBusy(false); } }
  async function renameConversation(conversation: Conversation) { setOpenMenu(null); const title = window.prompt("Rename conversation", conversation.title)?.trim(); if (!title || title === conversation.title) return; try { const response = await api(`/conversations/${conversation.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ title }) }); if (!response.ok) throw new Error("Could not rename this conversation."); setConversations((items) => items.map((item) => item.id === conversation.id ? { ...item, title } : item)); } catch (cause) { setHistoryError(cause instanceof Error ? cause.message : "Could not rename this conversation."); } }
